import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"童溪易傳","description":"童溪易傳 - 童溪易傳","frontmatter":{"title":"童溪易傳","description":"童溪易傳 - 童溪易傳"},"headers":[],"relativePath":"classics/tongxi/001.md","filePath":"classics/tongxi/001.md"}'),r={name:"classics/tongxi/001.md"};function o(i,a,c,p,d,u){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"童溪易傳",tabindex:"-1"},[n("童溪易傳 "),e("a",{class:"header-anchor",href:"#童溪易傳","aria-label":"Permalink to “童溪易傳”"},"​")],-1),e("p",null,"欽定四庫全書經部一童溪易傳易類提要",-1),e("p",null,"傳字景孟，寧德人。淳熙八年進士，官韶州教授。董真卿以為臨安人。朱彝尊經義考謂是書前有寧德林焞序，稱與宗傳「生同方，學同學，同及辛丑第」，則雲臨安人者誤矣。宗傳之說，大概祧梁、孟而宗王弼，故其書惟憑心悟，力斥象數之弊，至譬於誤注本草之殺人。焞序述宗傳之論，有",-1),e("p",null,"「性本無說，聖人本無言」之語，不免涉於異學，與楊簡慈湖易傳宗旨相同。蓋弼易祖尚元虛，以闡發義理，漢學至是而始變。宋儒掃除古法，實從是萌芽。然胡、程祖其義理而歸諸人事，故似淺近而醇實；宗傳及簡祖其元虛而索諸性天，故似高深而幻窅。考沈作哲作寓簡，第一卷多談易理，大抵以佛氏為宗。作哲為紹興五年進士，其作寓簡在淳熙元年，正與宗傳同時。然則以禪言易，起於南宋之初，特作哲無成書，宗傳及簡則各有成編，顯闡別經耳。春秋之書事，檀弓之說禮，必謹其變之所始。錄存是編，俾學者知明萬曆以後，動以心學說易，流別於此。二人亦說周禮者，存俞庭椿、邱葵意也。乾隆四十五年十二月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。易傳原序：",-1),e("p",null,"「易」不可以「易」言也。蓋自漢魏以來，世之言易者特多於他經，而其失也，比之言他經者亦多，此其故何也？易而言之之過也。夫人之情，有所難乎此也，則必有所畏謹乎此，而後獲免輕議乎此之失。苟惟有所易也，則將爭奇競巧，而不知中庸之為至德；騁私任臆，而不知正直之為王道。如是則擇焉不精，語焉不詳，貿貿然不知朱紫苗莠之固有其辨，而吠聲覘影之流始受其誤矣。昔者夫子蓋嘗致謹乎此也，觀其言曰：「加我數年，五十以學易，可以無大過矣。」夫學易而可以無易之過，此豈童心淺智者之所能為也？故聖如夫子，亦曰：「吾猶有待焉爾。」聖人之心，其不敢有所易如此也。而客有注易與本草孰先之問，為陶隱居者則告之曰：「易先。」其說曰：「注易誤，不至殺人；本草誤，人有不得其死者。」嗚呼！自斯「人不至殺人」之言一發，而易之誤自此始矣。世之輕議是經者，始紛紛矣。夫豈知本草誤，誤人命；注易誤，誤人心。人心一誤，則形存性亡，為鬼蜮，為禽獸，將無所不至，其禍不亦慘於殺人矣乎？隱居之言曰：「本草誤，人有不得其死者。」殊不知注易誤，人有不得其生者，可謂智乎？或曰：「若之何而可以無易之過，如吾聖人之學易矣乎？」曰：「竊嘗聞之，綱一舉而目張，領一挈而裘順，天下之有是物也，孰從而然歟？是故有所謂形而上者之制乎命，而後是物也得以肇其長短小大之形，吉凶消長之變。世之言易者，孰不曰舍是數不可以言易也，舍是象不可以言易也。而聖如夫子，亦必曰是數與象，易所不廢也。然所以為是數與象者，或不知其說焉。則自一以往，而有不可勝計之數，自形色貌象以往，而有不可勝計之象，雖夫子亦末如之何矣。何也？聖人之於易，徒知據乎其會而已矣。據其會則凡憧憧於吾前者，莫吾眩也。聖人之於易也，徒知立乎其顛而已矣，立其顛則凡紛紛乎吾下者，莫吾度也。然則是數也，是象也，不知務其所以然之說也，而可乎？夫苟舍是而役役於不可勝計之地，此夫子所謂易之過也。然則舍數與象不可以為易，而其過也，乃數與象也，則金石草木所以為本草也，而其殺人也，乃金石草木也。天下同知本草誤，誤人命，而不知易誤，誤人心。籲，亦異哉！餘不敏，一經之教，奉以周旋有日矣。」然學愈久而心愈雜，故雖疲神剔思於此，非不勤且至也，而未嘗敢下輕議之筆。雖然，抑嘗思之，加我之年，亦行甫及矣，進無用於時，退無補於身，不於此時也而有所勉焉，豈其志歟？若夫所謂大過，亦不敢自謂果可無也，願就有道而正焉。王宗傳謹述。",-1),e("p",null,"性本無說，聖人本無言，童溪之論性然也。易，儘性書也，而何至於多言？我知之矣。六丁敕易在天，三爻吞易在人。天而人之，易其顯乎？餘與童溪生同方，學同學，同及辛丑第，知其出處最詳。公性能酒，飲已輒論易，嘗曰：「吾遠祖文中不善辨，為負苓者詘。使與我遇，當瞪目張膽滅其苓而飢之，曰：爾不有於人，又何有於身？」自是與人論易不倦，而於二係為詳。出其門者十九青紫。既第之三年，教授曲江，越二年而書成，大書其影曰三十卷之易書，自謂無愧三聖，其篤於自信者歟？公姓王，諱宗傳，字景孟，世謂天下王景孟，則其人也。開禧更元，族子駉客武陵，以書來曰：「劉君日新將以童溪易傳膏馥天下後世，叔大夫父當序。」是以序。儒林郎、知衢州開化縣主管勸農公事林焞炳叔序。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
